using System;
using System.IO;
using System.Collections.Generic;
using ScoreModern.RecoveredFragments;
class BufferedDrawProof {
 class Memory:IBufferedDrawMemory {public Dictionary<ushort,ushort> Words=new Dictionary<ushort,ushort>();public List<string> Events=new List<string>();public ushort ReadWord(ushort s,ushort o){ushort v;Words.TryGetValue(o,out v);Events.Add("R:"+s+":"+o+":"+v);return v;}public void WriteWord(ushort s,ushort o,ushort v){Events.Add("W:"+s+":"+o+":"+v);Words[o]=v;}public Memory Copy(){Memory m=new Memory();foreach(var p in Words)m.Words[p.Key]=p.Value;return m;}}
 static BufferedDrawWords Run(int mode,Memory m,ushort ds,ushort ax){return mode==0?BufferedDrawControl.DecodeMarker(m,ds,ax):mode==1?BufferedDrawControl.SelectRasterPath(m,ds):BufferedDrawControl.UpdatePosition(m,ds,ax);}
 static BufferedDrawWords Interpret(int mode,byte[] code,Memory m,ushort ds,ushort ax){int pc=0,cmp=0;ushort cx=0;bool branch=false;Func<byte> f=()=>code[pc++];Func<ushort> word=()=>{byte l=f();return (ushort)(l|f()<<8);};while(pc<code.Length){switch(f()){
  case 0x3d:cmp=(short)ax-(short)word();break;case 0x7f:sbyte gt=(sbyte)f();if(cmp>0)return new BufferedDrawWords{AX=ax};break;
  case 0x05:ax=(ushort)(ax+word());break;case 0xa3:m.WriteWord(ds,word(),ax);break;
  case 0xeb:sbyte j=(sbyte)f();if(0x41+pc+j!=0x7a)throw new Exception("Marker exit");return new BufferedDrawWords{AX=ax,Branch=true};
  case 0xa1:ax=m.ReadWord(ds,word());break;case 0x8b:if(f()!=0x0e)throw new Exception("MOV CX");cx=m.ReadWord(ds,word());break;
  case 0x80:if(f()!=0xf9)throw new Exception("CMP CL");cmp=(sbyte)(byte)cx-(sbyte)f();break;case 0x7e:sbyte le=(sbyte)f();branch=cmp>0;break;
  case 0x89:if(f()!=0x0e)throw new Exception("MOV CX memory");m.WriteWord(ds,word(),cx);break;default:throw new Exception("Opcode");
 }}return new BufferedDrawWords{AX=ax,CX=cx,Branch=branch};}
 static bool Equal(BufferedDrawWords a,BufferedDrawWords b){return a.AX==b.AX&&a.CX==b.CX&&a.Branch==b.Branch;}
 static ushort H(string s){return Convert.ToUInt16(s,16);}
 static int Main(string[] args){try{byte[] raw=File.ReadAllBytes(args[0]);int[] sites={0x1bf30+0x41,0x18070+0x738,0x18070+0xb1c},lengths={13,12,11};string[] identities={"3D-A8-80-7F-09-05-BC-7F-A3-48-AC-EB-2C","A1-42-AC-8B-0E-48-AC-80-F9-00-7E-05","8B-0E-40-AC-89-0E-44-AC-A3-46-AC"};byte[][] code=new byte[3][];for(int n=0;n<3;n++){code[n]=new byte[lengths[n]];Array.Copy(raw,sites[n],code[n],0,lengths[n]);if(BitConverter.ToString(code[n])!=identities[n])throw new Exception("Original identity");}
  if(args.Length>1){int mode=int.Parse(args[1]);string p=args[2],before=args[3],after=args[4],liveName=args[5];ushort ds=H(args[6]),ax=H(args[7]);byte[] b=File.ReadAllBytes(Path.Combine(p,before)),a=File.ReadAllBytes(Path.Combine(p,after)),live=File.ReadAllBytes(Path.Combine(p,liveName));if(b.Length!=65536||a.Length!=65536||live.Length<lengths[mode])throw new Exception("Capture length");for(int i=0;i<lengths[mode];i++)if(live[i]!=code[mode][i])throw new Exception("Live code");Memory m=new Memory();for(int i=0;i<65536;i+=2)m.Words[(ushort)i]=(ushort)(b[i]|b[i+1]<<8);BufferedDrawWords r=Run(mode,m,ds,ax);if(!Equal(r,new BufferedDrawWords{AX=H(args[8]),CX=H(args[9]),Branch=bool.Parse(args[10])}))throw new Exception("Runtime words/branch");for(int i=0;i<65536;i+=2){ushort v=m.Words[(ushort)i];if((byte)v!=a[i]||(byte)(v>>8)!=a[i+1])throw new Exception("Runtime DS");}Console.WriteLine("PASS original drawing-control block "+mode+": exact live code, projected words/branch and all 65536 DS bytes, zero exclusions.");return 0;}
  int count=0;for(int n=0;n<65536;n++)for(int pattern=0;pattern<4;pattern++)for(int mode=0;mode<3;mode++){Memory seed=new Memory();seed.Words[0xac40]=(ushort)(n*13+pattern);seed.Words[0xac42]=(ushort)(n^0xa55a);seed.Words[0xac44]=(ushort)(pattern*777);seed.Words[0xac46]=(ushort)(n+pattern);seed.Words[0xac48]=(ushort)n;Memory a=seed.Copy(),b=seed.Copy();BufferedDrawWords x=Run(mode,a,0x871e,(ushort)n),y=Interpret(mode,code[mode],b,0x871e,(ushort)n);if(!Equal(x,y)||a.Events.Count!=b.Events.Count||a.Words.Count!=b.Words.Count)throw new Exception("Model result");for(int i=0;i<a.Events.Count;i++)if(a.Events[i]!=b.Events[i])throw new Exception("Read/write order");foreach(var e in a.Words)if(b.Words[e.Key]!=e.Value)throw new Exception("Memory");count++;}Console.WriteLine("PASS "+count+" original-instruction drawing-control comparisons: all input/mode words, signed thresholds/low-byte dispatch, wrapping, position words and ordered effects.");Console.WriteLine("Scope: three word/memory/branch projections only, not a complete decoder, rasterizer, flags/interrupt/return ABI or rendering implementation.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
